describe('WebSocket Real-Time UI Updates', () => {
  const WS_URL = 'ws://localhost:8080';
  let ws;

  beforeEach(() => {
    cy.visit('/');
    cy.window().then((win) => {
      ws = new WebSocket(WS_URL);
    });
  });

  afterEach(() => {
    if (ws && ws.readyState === WebSocket.OPEN) {
      ws.close();
    }
  });

  it('should establish WebSocket connection and update UI with real-time data', () => {
    cy.window().then((win) => {
      return new Promise((resolve) => {
        const socket = new WebSocket(WS_URL);

        socket.onopen = () => {
          cy.get('[data-testid="connection-status"]')
            .should('contain', 'Connected')
            .should('have.css', 'color', 'rgb(0, 128, 0)');

          socket.send(JSON.stringify({ type: 'subscribe', channel: 'updates' }));
        };

        socket.onmessage = (event) => {
          const data = JSON.parse(event.data);

          cy.get('[data-testid="message-count"]').then(($el) => {
            const currentCount = parseInt($el.text());
            expect(currentCount).to.be.greaterThan(0);
          });

          cy.get('[data-testid="latest-message"]')
            .should('contain', data.message)
            .should('be.visible');

          cy.get('[data-testid="timestamp"]').should('not.be.empty');

          socket.close();
          resolve();
        };

        socket.onerror = () => {
          throw new Error('WebSocket connection failed');
        };
      });
    });
  });

  it('should handle WebSocket reconnection on connection loss', () => {
    cy.window().then((win) => {
      return new Promise((resolve) => {
        const socket = new WebSocket(WS_URL);
        let reconnectAttempts = 0;
        const maxReconnectAttempts = 3;

        socket.onopen = () => {
          cy.get('[data-testid="connection-status"]').should('contain', 'Connected');

          if (reconnectAttempts === 0) {
            socket.close();
          }
        };

        socket.onclose = () => {
          cy.get('[data-testid="connection-status"]').should('contain', 'Disconnected');

          if (reconnectAttempts < maxReconnectAttempts) {
            reconnectAttempts++;
            cy.wait(500).then(() => {
              const newSocket = new WebSocket(WS_URL);

              newSocket.onopen = () => {
                cy.get('[data-testid="reconnect-count"]').should(
                  'contain',
                  reconnectAttempts.toString()
                );
                newSocket.close();
                resolve();
              };

              newSocket.onerror = () => {
                throw new Error(`Reconnection attempt ${reconnectAttempts} failed`);
              };
            });
          }
        };

        socket.onerror = () => {
          throw new Error('Initial WebSocket connection failed');
        };
      });
    });
  });

  it('should handle multiple concurrent WebSocket messages without data loss', () => {
    cy.window().then((win) => {
      return new Promise((resolve) => {
        const socket = new WebSocket(WS_URL);
        const receivedMessages = [];
        const expectedMessageCount = 5;

        socket.onopen = () => {
          cy.get('[data-testid="connection-status"]').should('contain', 'Connected');

          for (let i = 0; i < expectedMessageCount; i++) {
            socket.send(
              JSON.stringify({
                type: 'message',
                id: i,
                content: `Message ${i}`,
              })
            );
          }
        };

        socket.onmessage = (event) => {
          const data = JSON.parse(event.data);
          receivedMessages.push(data);

          cy.get('[data-testid="message-list"]').within(() => {
            cy.get('[data-testid="message-item"]').should(
              'have.length',
              receivedMessages.length
            );
          });

          if (receivedMessages.length === expectedMessageCount) {
            cy.get('[data-testid="message-count"]').should(
              'contain',
              expectedMessageCount.toString()
            );

            expect(receivedMessages).to.have.lengthOf(expectedMessageCount);
            receivedMessages.forEach((msg, index) => {
              expect(msg.id).to.equal(index);
            });

            socket.close();
            resolve();
          }
        };

        socket.onerror = () => {
          throw new Error('WebSocket error during concurrent message test');
        };
      });
    });
  });

  it('should display error message when WebSocket connection fails', () => {
    const invalidWsUrl = 'ws://invalid-host:9999';

    cy.window().then((win) => {
      return new Promise((resolve) => {
        const socket = new WebSocket(invalidWsUrl);

        socket.onerror = () => {
          cy.get('[data-testid="error-message"]')
            .should('be.visible')
            .should('contain', 'Connection failed');

          cy.get('[data-testid="connection-status"]').should('contain', 'Error');

          cy.get('[data-testid="retry-button"]').should('be.visible').and('be.enabled');

          resolve();
        };

        socket.onopen = () => {
          throw new Error('Should not connect to invalid host');
        };
      });
    });
  });
});
